/* Ghandi Home — sales, contacts, expenses, shifts, reports, users, invoice designer, backup, settings */
'use strict';
function pmName(k) { var p = S().payMethods.filter(function (x) { return x[0] === k; })[0]; return p ? (lang() === 'en' ? p[2] : p[1]) : k; }
function dateRangeBar(id, st) {
  return '<div class="row wrap" id="' + id + '"><div class="seg">' + [['today', 'اليوم', 'Today'], ['yest', 'أمس', 'Yesterday'], ['week', '7 أيام', '7 days'], ['month', 'هذا الشهر', 'This month'], ['custom', 'مخصص', 'Custom']].map(function (r) { return '<button data-r="' + r[0] + '" class="' + (st.range === r[0] ? 'on' : '') + '">' + L(r[1], r[2]) + '</button>'; }).join('') + '</div><input type="date" class="in" style="width:160px" data-f value="' + st.from + '"><input type="date" class="in" style="width:160px" data-t value="' + st.to + '"></div>';
}
function bindRange(id, st, cb) {
  var set = function (r) {
    var t = new Date(), f = new Date(); st.range = r;
    if (r === 'yest') { f.setDate(f.getDate() - 1); t = new Date(f); } else if (r === 'week') f.setDate(f.getDate() - 6); else if (r === 'month') f.setDate(1);
    if (r !== 'custom') { st.from = U.today(f); st.to = U.today(t); }
  };
  $$('#' + id + ' [data-r]').forEach(function (b) { b.onclick = function () { set(b.dataset.r); cb(); }; });
  $('#' + id + ' [data-f]').onchange = function () { st.range = 'custom'; st.from = this.value; cb(); };
  $('#' + id + ' [data-t]').onchange = function () { st.range = 'custom'; st.to = this.value; cb(); };
}
function rangeMs(st) { var f = new Date(st.from + 'T00:00:00').getTime(), t = new Date(st.to + 'T00:00:00').getTime() + 864e5; return [f, t]; }

/* ================= SALES HISTORY / RETURNS ================= */
Views.sales = {
  st: { range: 'today', from: U.today(), to: U.today(), q: '' },
  render: function (el) {
    var V = Views.sales, st = V.st;
    el.innerHTML = '<div class="row wrap" style="margin-bottom:14px">' + dateRangeBar('sr', st) + '<div class="grow"></div><input class="in" id="sq" style="width:220px" placeholder="' + L('رقم الفاتورة…', 'Invoice #…') + '" value="' + U.esc(st.q) + '"></div><div class="tbl-wrap" id="stb"></div>';
    bindRange('sr', st, function () { V.render(el); });
    $('#sq').oninput = function () { st.q = this.value; V.table(); }; $('#sq').onkeydown = function (e) { if (e.key === 'Enter') { var s = Store.db.sales.filter(function (x) { return String(x.no) === st.q.replace(/\D/g, ''); })[0]; if (s) V.open(s); } };
    V.table();
  },
  table: function () {
    var V = Views.sales, st = V.st, r = rangeMs(st), mine = !can('shifts.all') && App.user.role !== 'admin';
    var list = Store.db.sales.filter(function (s) { if (st.q) return String(s.no).indexOf(st.q.replace(/\D/g, '')) === 0; return s.date >= r[0] && s.date < r[1] && (!mine || s.user === App.user.id); }).reverse().slice(0, 500);
    $('#stb').innerHTML = '<table class="t"><tr><th>#</th><th>' + L('التاريخ', 'Date') + '</th><th>' + L('النوع', 'Type') + '</th><th>' + L('العميل', 'Customer') + '</th><th>' + L('القطع', 'Items') + '</th><th>' + L('الدفع', 'Payment') + '</th><th>' + L('الإجمالي', 'Total') + '</th><th>' + L('الكاشير', 'Cashier') + '</th><th></th></tr>' +
      (list.length ? list.map(function (s) { var c = Store.db.customers.filter(function (x) { return x.id === s.customer; })[0]; return '<tr data-id="' + s.id + '" style="cursor:pointer' + (s.void ? ';opacity:.45;text-decoration:line-through' : '') + '"><td class="num"><b>' + s.no + '</b></td><td class="num">' + U.dt(s.date) + '</td><td>' + (s.type === 'return' ? '<span class="chip bad">' + L('مرتجع', 'Return') + '</span>' : '<span class="chip ok">' + L('بيع', 'Sale') + '</span>') + '</td><td>' + U.esc(c ? c.name : '—') + '</td><td class="num">' + s.items.reduce(function (a, i) { return a + i.qty; }, 0) + '</td><td>' + Object.keys(s.payments || {}).map(function (k) { return '<span class="chip">' + pmName(k) + '</span>'; }).join(' ') + (s.credit ? '<span class="chip warn">' + L('آجل', 'Credit') + '</span>' : '') + '</td><td><b>' + M(s.total) + '</b></td><td>' + U.esc(s.userName) + '</td><td>' + ic('receipt', 16) + '</td></tr>'; }).join('') : '<tr><td colspan="9"><div class="empty">' + L('لا توجد فواتير في هذه الفترة', 'No invoices in this period') + '</div></td></tr>') + '</table>';
    $$('#stb tr[data-id]').forEach(function (r) { r.onclick = function () { V.open(Store.db.sales.filter(function (s) { return s.id === r.dataset.id; })[0]); }; });
  },
  open: function (s) {
    var returned = {}; Store.db.sales.forEach(function (x) { if (x.type === 'return' && x.ref === s.id && !x.void) x.items.forEach(function (i) { returned[i.pid] = (returned[i.pid] || 0) + i.qty; }); });
    var m = Modal.open({ size: 'wide', title: (s.type === 'return' ? L('مرتجع #', 'Return #') : L('فاتورة #', 'Invoice #')) + s.no, body: '<div class="grid" style="grid-template-columns:1fr 1fr;gap:18px"><div class="preview-wrap" style="min-height:0;padding:14px"><div class="receipt">' + Receipt.html(s) + '</div></div><div class="col">' +
      (s.type === 'sale' && !s.void && can('pos.return') ? '<div class="card"><h3>' + ic('ret', 17) + L('مرتجع من هذه الفاتورة', 'Return items') + '</h3>' + s.items.map(function (i, x) { var left = i.qty - (returned[i.pid] || 0); return '<div class="list-row"><div class="grow"><b class="small">' + U.esc(i.name) + '</b><div class="muted small">' + L('مباع ', 'sold ') + i.qty + ' · ' + L('متاح للإرجاع ', 'returnable ') + left + '</div></div><input class="in num" type="number" min="0" max="' + left + '" data-rq="' + x + '" value="0" style="width:70px" ' + (left ? '' : 'disabled') + '></div>'; }).join('') + '<button class="btn bad" id="dor" style="width:100%;margin-top:10px">' + L('تنفيذ المرتجع', 'Process return') + '</button></div>' : '') +
      '<div class="row wrap">' + (can('pos.reprint') ? '<button class="btn pri" id="rp">' + ic('print') + L('طباعة', 'Print') + '</button>' : '') + (can('sales.delete') && !s.void ? '<button class="btn" id="vd" style="color:var(--bad)">' + ic('trash') + L('إلغاء الفاتورة', 'Void invoice') + '</button>' : '') + '</div>' + (s.void ? '<div class="chip bad">' + L('ملغاة بواسطة ', 'Voided by ') + U.esc(s.voidBy) + '</div>' : '') + '</div></div>' });
    if ($('#rp', m)) $('#rp', m).onclick = function () { Receipt.print(s); };
    if ($('#vd', m)) $('#vd', m).onclick = function () { Modal.confirm(L('إلغاء الفاتورة سيرجع الكميات للمخزن. متابعة؟', 'Voiding restores the stock. Continue?'), function () { if (typeof Sales.onVoid === 'function') Sales.onVoid(s); s.items.forEach(function (i) { Store.move(i.pid, s.type === 'return' ? -i.qty : i.qty, 'void', '#' + s.no); }); if (s.customer && s.credit) { var c = Store.db.customers.filter(function (x) { return x.id === s.customer; })[0]; if (c) c.balance = U.r2(U.n(c.balance) - (s.type === 'return' ? -s.credit : s.credit)); } s.void = true; s.voidBy = App.user.name; Store.log('void', '#' + s.no); Store.save(); Modal.close(m); toast(L('تم الإلغاء', 'Voided'), 'ok'); Views.sales.table(); }); };
    if ($('#dor', m)) $('#dor', m).onclick = function () {
      if (shiftsOn() && !App.shift) return toast(L('افتح وردية أولاً', 'Open a shift first'), 'bad');
      var items = []; $$('[data-rq]', m).forEach(function (i) { var q = Math.min(U.n(i.value), U.n(i.max)); if (q > 0) { var it = s.items[+i.dataset.rq]; items.push({ pid: it.pid, name: it.name, qty: q, price: it.price, cost: it.cost }); } });
      if (!items.length) return;
      var sub = items.reduce(function (a, i) { return a + i.qty * i.price; }, 0), ratio = s.subtotal ? s.discount / s.subtotal : 0, disc = U.r2(sub * ratio), tot = U.r2(sub - disc);
      var r = Sales.create({ type: 'return', ref: s.id, items: items, customer: s.customer, tier: s.tier, subtotal: U.r2(sub), discount: disc, total: tot, payments: { cash: tot }, paid: tot });
      Modal.close(m); Receipt.print(r); toast(L('تم المرتجع — رد للعميل ', 'Return done — refund ') + U.money(tot), 'ok'); Views.sales.table();
    };
  }
};

/* ================= CONTACTS ================= */
Views.contacts = {
  tab: 'customers',
  render: function (el) {
    var V = Views.contacts; if (V.only) V.tab = V.only; if (!can(V.tab)) V.tab = can('customers') ? 'customers' : 'suppliers';
    var list = Store.db[V.tab], isC = V.tab === 'customers';
    el.innerHTML = '<div class="row" style="margin-bottom:14px"><div class="seg">' + (can('customers') && !V.only ? '<button data-t="customers" class="' + (isC ? 'on' : '') + '">' + L('العملاء', 'Customers') + '</button>' : '') + (can('suppliers') ? '<button data-t="suppliers" class="' + (!isC ? 'on' : '') + '">' + L('الموردين', 'Suppliers') + '</button>' : '') + '</div><input class="in" id="cq" style="width:240px" placeholder="' + L('بحث…', 'Search…') + '"><div class="grow"></div><button class="btn pri" id="cadd">' + ic('plus') + L('إضافة', 'Add') + '</button></div><div class="tbl-wrap" id="ctb"></div>';
    $$('[data-t]').forEach(function (b) { b.onclick = function () { V.tab = b.dataset.t; V.render(el); }; });
    var draw = function () {
      var q = U.norm($('#cq').value), rows = list.filter(function (c) { return !q || U.norm(c.name + ' ' + (c.phone || '')).indexOf(q) >= 0; });
      $('#ctb').innerHTML = '<table class="t"><tr><th>' + L('الاسم', 'Name') + '</th><th>' + L('الموبايل', 'Phone') + '</th>' + (isC ? '<th>' + L('شريحة السعر', 'Price tier') + '</th><th>' + L('نقاط', 'Points') + '</th>' : '') + '<th>' + (isC ? L('عليه (آجل)', 'Owes us') : L('له (مستحق)', 'We owe')) + '</th><th></th></tr>' + (rows.length ? rows.map(function (c) { return '<tr><td><b>' + U.esc(c.name) + '</b><div class="muted small">' + U.esc(c.note || '') + '</div></td><td class="num">' + U.esc(c.phone || '') + '</td>' + (isC ? '<td>' + (c.tier != null && c.tier !== '' ? '<span class="chip">' + tierName(+c.tier) + '</span>' : '—') + '</td><td class="num">' + U.n(c.points) + '</td>' : '') + '<td>' + (U.n(c.balance) ? '<b style="color:var(--bad)">' + M(c.balance) + '</b>' : '<span class="muted">0</span>') + '</td><td style="white-space:nowrap"><button class="btn sm" data-pay="' + c.id + '">' + ic('wallet', 15) + L('سداد', 'Settle') + '</button> <button class="btn ghost sm" data-e="' + c.id + '">' + ic('edit', 15) + '</button></td></tr>'; }).join('') : '<tr><td colspan="6"><div class="empty">—</div></td></tr>') + '</table>';
      $$('[data-e]').forEach(function (b) { b.onclick = function () { V.edit(list.filter(function (c) { return c.id === b.dataset.e; })[0]); }; });
      $$('[data-pay]').forEach(function (b) { b.onclick = function () { var c = list.filter(function (x) { return x.id === b.dataset.pay; })[0]; Modal.prompt(L('سداد — ', 'Settle — ') + U.esc(c.name), L('المبلغ', 'Amount'), U.n(c.balance), function (v) { v = U.n(v); if (!v) return; c.balance = U.r2(U.n(c.balance) - v); (c.payments = c.payments || []).push({ t: Date.now(), v: v, u: App.user.name, shift: App.shift ? App.shift.id : '' }); Store.log(V.tab + '.pay', c.name + ' ' + v); Store.save(); draw(); toast(L('تم التسجيل', 'Recorded'), 'ok'); }, 'number'); }; });
    };
    $('#cq').oninput = draw; $('#cadd').onclick = function () { V.edit(null); }; V.el = el; draw();
  },
  edit: function (c) {
    var V = Views.contacts, isC = V.tab === 'customers', d = c || { name: '', phone: '', note: '', tier: '', balance: 0, points: 0 };
    var m = Modal.open({ title: c ? L('تعديل', 'Edit') : L('إضافة', 'Add'), body: '<div class="col"><label class="f">' + L('الاسم', 'Name') + '<input class="in" id="cn" autofocus value="' + U.esc(d.name) + '"></label><label class="f">' + L('الموبايل', 'Phone') + '<input class="in num" id="cp" value="' + U.esc(d.phone || '') + '"></label>' + (isC ? '<label class="f">' + L('شريحة سعر ثابتة لهذا العميل', 'Fixed price tier for this customer') + '<select class="in" id="ct"><option value="">—</option>' + S().tiers.map(function (t, i) { return '<option value="' + i + '" ' + (String(d.tier) === String(i) ? 'selected' : '') + '>' + tierName(i) + '</option>'; }).join('') + '</select></label>' : '') + '<label class="f">' + L('ملاحظات', 'Notes') + '<input class="in" id="cno" value="' + U.esc(d.note || '') + '"></label>' + (!c ? '<label class="f">' + L('رصيد افتتاحي', 'Opening balance') + '<input class="in num" type="number" id="cb" value="0"></label>' : '') + '</div>', foot: '<button class="btn pri" id="cs">' + L('حفظ', 'Save') + '</button>' });
    $('#cs', m).onclick = function () { var n = $('#cn', m).value.trim(); if (!n) return; var t = c || { id: U.id(), balance: U.n($('#cb', m).value), points: 0 }; t.name = n; t.phone = $('#cp', m).value.trim(); t.note = $('#cno', m).value; if (isC) t.tier = $('#ct', m).value; if (!c) Store.db[V.tab].push(t); Store.save(); Modal.close(m); V.render(V.el); };
  }
};

/* ================= EXPENSES ================= */
Views.expenses = function (el) {
  var db = Store.db, cats = ['إيجار', 'كهرباء', 'مرتبات', 'نقل', 'بوفيه', 'صيانة', 'أكياس وتغليف', 'أخرى'];
  el.innerHTML = '<div class="grid" style="grid-template-columns:330px 1fr;gap:16px;align-items:start"><div class="card col"><h3>' + ic('wallet', 18) + L('مصروف جديد', 'New expense') + '</h3><label class="f">' + L('البند', 'Category') + '<input class="in" id="ec" list="ecl"><datalist id="ecl">' + cats.map(function (c) { return '<option value="' + c + '">'; }).join('') + '</datalist></label><label class="f">' + L('المبلغ', 'Amount') + '<input class="in num" type="number" id="ea"></label><label class="f">' + L('ملاحظة', 'Note') + '<input class="in" id="en"></label><label class="row small"><input type="checkbox" class="sw" id="ed" checked> ' + L('من درج الكاشير', 'Paid from cash drawer') + '</label><button class="btn pri" id="es">' + L('حفظ', 'Save') + '</button></div><div class="tbl-wrap"><table class="t"><tr><th>' + L('التاريخ', 'Date') + '</th><th>' + L('البند', 'Category') + '</th><th>' + L('ملاحظة', 'Note') + '</th><th>' + L('المبلغ', 'Amount') + '</th><th>' + L('بواسطة', 'By') + '</th></tr>' + (db.expenses.length ? db.expenses.slice().reverse().slice(0, 300).map(function (e) { return '<tr><td class="num">' + U.dt(e.t) + '</td><td><span class="chip">' + U.esc(e.cat) + '</span></td><td>' + U.esc(e.note) + '</td><td><b>' + M(e.v) + '</b></td><td>' + U.esc(e.by) + '</td></tr>'; }).join('') : '<tr><td colspan="5"><div class="empty">—</div></td></tr>') + '</table></div></div>';
  $('#es').onclick = function () { var v = U.n($('#ea').value); if (!v) return; db.expenses.push({ id: U.id(), t: Date.now(), cat: $('#ec').value || L('أخرى', 'Other'), v: v, note: $('#en').value, by: App.user.name, drawer: $('#ed').checked, shift: App.shift ? App.shift.id : '' }); Store.log('expense', v); Store.save(); toast(L('تم الحفظ', 'Saved'), 'ok'); Views.expenses(el); };
};

/* ================= SHIFTS ================= */
Views.shifts = {
  calc: function (sh) {
    var r = { cash: 0, other: {}, sales: 0, returns: 0, count: 0, exp: 0, coll: 0 };
    Store.db.sales.forEach(function (s) { if (s.shift !== sh.id || s.void) return; var sg = s.type === 'return' ? -1 : 1; if (s.type === 'return') r.returns += s.total; else { r.sales += s.total; r.count++; } Object.keys(s.payments || {}).forEach(function (k) { if (k === 'cash') r.cash += sg * s.payments[k]; else r.other[k] = (r.other[k] || 0) + sg * s.payments[k]; }); });
    Store.db.expenses.forEach(function (e) { if (e.shift === sh.id && e.drawer) r.exp += e.v; });
    Store.db.customers.forEach(function (c) { (c.payments || []).forEach(function (p) { if (p.shift === sh.id) r.coll += p.v; }); });
    r.expected = U.r2(U.n(sh.openCash) + r.cash - r.exp + r.coll); return r;
  },
  openPrompt: function (el) {
    el.innerHTML = '<div style="display:grid;place-items:center;height:100%"><div class="card col" style="width:400px;text-align:center;padding:30px"><div class="logo" style="margin:0 auto;width:56px;height:56px">' + ic('clock', 26) + '</div><h2 style="margin:6px 0 0">' + L('فتح وردية جديدة', 'Open a new shift') + '</h2><div class="muted">' + L('أدخل النقدية الموجودة في الدرج لبدء البيع', 'Enter the cash in the drawer to start selling') + '</div><input class="in num" type="number" id="oc" placeholder="0.00" style="font-size:24px;text-align:center" autofocus><button class="btn pri lg" id="ob">' + L('بدء الوردية', 'Start shift') + '</button></div></div>';
    $('#oc').focus(); var go2 = function () { var db = Store.db; db.seq.shift++; App.shift = { id: U.id(), no: db.seq.shift, user: App.user.id, userName: App.user.name, openAt: Date.now(), openCash: U.n($('#oc').value) }; db.shifts.push(App.shift); Store.log('shift.open', App.shift.no); Store.save(); Shell.tick(); go('pos'); };
    $('#ob').onclick = go2; $('#oc').onkeydown = function (e) { if (e.key === 'Enter') go2(); };
  },
  render: function (el) {
    var V = Views.shifts, all = can('shifts.all') || App.user.role === 'admin';
    var list = Store.db.shifts.filter(function (s) { return all || s.user === App.user.id; }).slice().reverse().slice(0, 200);
    var cur = App.shift, r = cur ? V.calc(cur) : null;
    el.innerHTML = (cur ? '<div class="grid g4" style="margin-bottom:16px"><div class="card kpi hero"><div class="l">' + L('الوردية الحالية #', 'Current shift #') + cur.no + '</div><div class="v num">' + U.money(r.expected) + '</div><div class="small" style="opacity:.8">' + L('النقدية المتوقعة في الدرج', 'Expected cash in drawer') + '</div></div><div class="card kpi"><div class="l">' + L('المبيعات', 'Sales') + '</div><div class="v">' + M(r.sales) + '</div><div class="muted small">' + r.count + L(' فاتورة', ' invoices') + '</div></div><div class="card kpi"><div class="l">' + L('المرتجعات', 'Returns') + '</div><div class="v">' + M(r.returns) + '</div></div><div class="card kpi"><div class="l">' + L('مصروفات من الدرج', 'Drawer expenses') + '</div><div class="v">' + M(r.exp) + '</div></div></div><div class="row" style="margin-bottom:16px"><span class="muted">' + L('بدأت ', 'Started ') + U.dt(cur.openAt) + ' · ' + L('رصيد أول المدة ', 'Opening cash ') + U.money(cur.openCash) + Object.keys(r.other).map(function (k) { return ' · ' + pmName(k) + ': ' + U.money(r.other[k]); }).join('') + '</span><div class="grow"></div><button class="btn bad" id="sclose">' + ic('lock') + L('إغلاق الوردية', 'Close shift') + '</button></div>' : '<div class="card row" style="margin-bottom:16px"><span class="grow">' + L('لا توجد وردية مفتوحة لك', 'You have no open shift') + '</span><button class="btn pri" id="sopen">' + L('فتح وردية', 'Open shift') + '</button></div>') +
      '<div class="tbl-wrap"><table class="t"><tr><th>#</th><th>' + L('الموظف', 'User') + '</th><th>' + L('البداية', 'Opened') + '</th><th>' + L('النهاية', 'Closed') + '</th><th>' + L('المبيعات', 'Sales') + '</th><th>' + L('المتوقع', 'Expected') + '</th><th>' + L('الفعلي', 'Counted') + '</th><th>' + L('العجز/الزيادة', 'Over/short') + '</th></tr>' + list.map(function (s) { var c = V.calc(s), diff = s.closeAt ? U.r2(s.closeCash - c.expected) : null; return '<tr><td class="num">' + s.no + '</td><td>' + U.esc(s.userName) + '</td><td class="num">' + U.dt(s.openAt) + '</td><td class="num">' + (s.closeAt ? U.dt(s.closeAt) : '<span class="chip ok">' + L('مفتوحة', 'open') + '</span>') + '</td><td class="num">' + U.money(c.sales - c.returns) + '</td><td class="num">' + U.money(c.expected) + '</td><td class="num">' + (s.closeAt ? U.money(s.closeCash) + (App.user.role === 'admin' ? ' <button class="btn ghost sm" data-fixc="' + s.id + '" title="' + L('تصحيح المبلغ الفعلي', 'Correct counted cash') + '">✏️</button>' : '') : '—') + '</td><td>' + (diff == null ? '—' : '<span class="chip num ' + (Math.abs(diff) < .01 ? 'ok' : diff < 0 ? 'bad' : 'warn') + '">' + (diff > 0 ? '+' : '') + U.money(diff) + '</span>') + '</td></tr>'; }).join('') + '</table></div>';
    if ($('#sopen')) $('#sopen').onclick = function () { V.openPrompt(el); };
    if ($('#sclose')) $('#sclose').onclick = function () {
      var m = Modal.open({ title: L('إغلاق الوردية #', 'Close shift #') + cur.no, body: '<div class="col"><div class="muted">' + L('عدّ النقدية في الدرج وأدخلها', 'Count the cash in the drawer') + '</div><input class="in num" type="number" id="cc" autofocus style="font-size:24px;text-align:center"><div id="cd" class="chip" style="justify-content:center;font-size:14px"></div></div>', foot: '<button class="btn pri" id="cgo">' + L('إغلاق وطباعة التقرير', 'Close & print report') + '</button>' });
      $('#cc', m).oninput = function () { m._sure = false; $('#cgo', m).textContent = L('إغلاق وطباعة التقرير', 'Close & print report'); $('#cgo', m).classList.remove('bad'); var d = U.r2(U.n(this.value) - r.expected); $('#cd', m).className = 'chip ' + (Math.abs(d) < .01 ? 'ok' : d < 0 ? 'bad' : 'warn'); $('#cd', m).textContent = (d < 0 ? L('عجز ', 'Short ') : d > 0 ? L('زيادة ', 'Over ') : L('مطابق ✓', 'Balanced ✓')) + (d ? U.money(Math.abs(d)) : ''); };
      $('#cgo', m).onclick = function () {
        var cv = $('#cc', m).value.trim(); if (cv === '') { beep(false); $('#cc', m).focus(); return toast(L('اكتب المبلغ اللي عدّيته في الدرج الأول — لو الدرج فاضي اكتب 0', 'Enter the counted cash first — type 0 if the drawer is empty'), 'bad'); }
        var df = U.r2(U.n(cv) - r.expected); if (Math.abs(df) >= .01 && !m._sure) { m._sure = true; $('#cgo', m).textContent = (df < 0 ? L('فيه عجز ', 'Short ') : L('فيه زيادة ', 'Over ')) + U.money(Math.abs(df)) + L(' — اضغط تاني للتأكيد', ' — press again to confirm'); $('#cgo', m).classList.add('bad'); return; }
        cur.closeAt = Date.now(); cur.closeCash = U.n($('#cc', m).value); cur.expected = r.expected; Store.log('shift.close', cur.no); Store.saveNow(); Modal.close(m);
        var en = lang() === 'en', row = function (a, b) { return '<div style="display:flex;justify-content:space-between"><span>' + a + '</span><b>' + b + '</b></div>'; };
        Printer.print('<div class="rc" style="width:72mm;padding:3mm;font-size:12px"><div style="text-align:center;font-weight:800;font-size:16px">' + U.esc(shopName(en)) + '</div><div style="text-align:center">' + L('تقرير إغلاق وردية #', 'Shift close report #') + cur.no + '</div><hr>' + row(L('الموظف', 'User'), U.esc(cur.userName)) + row(L('من', 'From'), U.dt(cur.openAt)) + row(L('إلى', 'To'), U.dt(cur.closeAt)) + '<hr>' + row(L('رصيد أول', 'Opening'), U.money(cur.openCash)) + row(L('مبيعات', 'Sales'), U.money(r.sales)) + row(L('مرتجعات', 'Returns'), U.money(r.returns)) + row(L('نقدي', 'Cash'), U.money(r.cash)) + Object.keys(r.other).map(function (k) { return row(pmName(k), U.money(r.other[k])); }).join('') + row(L('تحصيلات', 'Collections'), U.money(r.coll)) + row(L('مصروفات', 'Expenses'), U.money(r.exp)) + '<hr>' + row(L('المتوقع', 'Expected'), U.money(r.expected)) + row(L('الفعلي', 'Counted'), U.money(cur.closeCash)) + row(L('الفرق', 'Difference'), U.money(cur.closeCash - r.expected)) + '</div>', { css: Receipt.css({ paper: '80' }), printer: S().printers.invoice, silent: S().printers.silent, receipt: true });
        if (S().backup.onShiftClose) Backup.run('shift');
        App.shift = null; Shell.tick(); V.render(el); toast(L('تم إغلاق الوردية', 'Shift closed'), 'ok');
      };
    };
  }
};

/* ================= REPORTS ================= */
Views.reports = {
  st: { range: 'month', from: U.today(new Date(new Date().setDate(1))), to: U.today() },
  render: function (el) {
    var V = Views.reports, st = V.st, r = rangeMs(st), sales = salesIn(r[0], r[1]), sum = sumSales(sales), prof = can('reports.profit');
    var byPm = {}, byUser = {}, byCat = {}, byProd = {}, days = {};
    sales.forEach(function (s) {
      var sg = s.type === 'return' ? -1 : 1;
      Object.keys(s.payments || {}).forEach(function (k) { byPm[k] = (byPm[k] || 0) + sg * s.payments[k]; }); if (s.credit) byPm._credit = (byPm._credit || 0) + sg * s.credit;
      byUser[s.userName] = (byUser[s.userName] || 0) + sg * s.total;
      var d = U.today(s.date); days[d] = (days[d] || 0) + sg * s.total;
      var _sub = s.items.reduce(function (a, i) { return a + i.qty * i.price; }, 0) || 1;
      s.items.forEach(function (i) { var p = Store.product(i.pid) || {}, c = p.cat || '—'; byCat[c] = (byCat[c] || 0) + sg * i.qty * i.price; var k = i.pid; byProd[k] = byProd[k] || { n: i.name, q: 0, v: 0, pr: 0, d: 0 }; byProd[k].q += sg * i.qty; byProd[k].v += sg * i.qty * i.price; if (sg > 0) byProd[k].d += ((U.n(i.base) > i.price ? (i.base - i.price) * i.qty : 0) + U.n(s.discount) * i.qty * i.price / _sub); byProd[k].pr += sg * i.qty * (i.price - i.cost); });
    });
    var exps = Store.db.expenses.filter(function (e) { return e.t >= r[0] && e.t < r[1]; }).reduce(function (a, e) { return a + e.v; }, 0);
    var tbl = function (obj, fmt) { var ks = Object.keys(obj).sort(function (a, b) { return obj[b] - obj[a]; }); return ks.length ? ks.map(function (k) { return '<div class="list-row"><span class="grow">' + U.esc(fmt ? fmt(k) : k) + '</span><b class="num">' + U.money(obj[k]) + '</b></div>'; }).join('') : '<div class="empty">—</div>'; };
    var prods = Object.keys(byProd).map(function (k) { return byProd[k]; }).sort(function (a, b) { return b.v - a.v; });
    var dk = []; for (var t = r[0]; t < r[1] && dk.length < 62; t += 864e5) dk.push(U.today(t));
    el.innerHTML = '<div class="row wrap" style="margin-bottom:14px">' + dateRangeBar('rr', st) + '<div class="grow"></div>' + (can('export') ? '<button class="btn" id="rx">' + ic('down') + 'Excel</button>' : '') + '<button class="btn" id="rpr">' + ic('print') + L('طباعة', 'Print') + '</button></div>' +
      '<div class="grid g4"><div class="card kpi hero"><div class="l">' + L('صافي المبيعات', 'Net sales') + '</div><div class="v">' + M(sum.total) + '</div><div class="small" style="opacity:.8">' + sum.count + L(' فاتورة', ' invoices') + '</div></div><div class="card kpi"><div class="l">' + L('المرتجعات', 'Returns') + '</div><div class="v">' + M(sum.ret) + '</div></div>' + (prof ? '<div class="card kpi"><div class="l">' + L('مجمل الربح', 'Gross profit') + '</div><div class="v" style="color:var(--ok)">' + M(sum.profit) + '</div><div class="muted small">' + (sum.total ? Math.round(sum.profit / sum.total * 100) : 0) + '% ' + L('هامش', 'margin') + '</div></div><div class="card kpi"><div class="l">' + L('صافي الربح بعد المصروفات', 'Net after expenses') + '</div><div class="v">' + M(sum.profit - exps) + '</div><div class="muted small">' + L('مصروفات ', 'Expenses ') + U.money(exps) + '</div></div>' : '<div class="card kpi"><div class="l">' + L('متوسط الفاتورة', 'Avg. ticket') + '</div><div class="v">' + M(sum.count ? sum.total / sum.count : 0) + '</div></div><div class="card kpi"><div class="l">' + L('القطع المباعة', 'Items sold') + '</div><div class="v num">' + sum.items + '</div></div>') + '</div>' +
      '<div class="card" style="margin-top:14px"><h3>' + ic('chart', 18) + L('المبيعات اليومية', 'Daily sales') + '</h3><canvas class="chart" id="rch"></canvas></div>' +
      '<div class="grid g3" style="margin-top:14px"><div class="card"><h3>' + L('طرق الدفع', 'Payment methods') + '</h3>' + tbl(byPm, function (k) { return k === '_credit' ? L('آجل', 'Credit') : pmName(k); }) + '</div><div class="card"><h3>' + L('حسب الكاشير', 'By cashier') + '</h3>' + tbl(byUser) + '</div><div class="card"><h3>' + L('حسب القسم', 'By category') + '</h3>' + tbl(byCat) + '</div></div>' +
      '<div class="card" style="margin-top:14px"><h3>' + ic('star', 18) + L('الأصناف المباعة', 'Products sold') + ' <span class="chip bad" style="font-size:13px">✂️ ' + L('إجمالي الخصومات: ', 'Total discounts: ') + U.money(prods.reduce(function (a, p) { return a + p.d; }, 0)) + '</span></h3><div class="tbl-wrap" style="max-height:420px"><table class="t"><tr><th>' + L('الصنف', 'Product') + '</th><th>' + L('الكمية', 'Qty') + '</th><th>' + L('المبيعات', 'Sales') + '</th><th>✂️ ' + L('الخصومات', 'Discounts') + '</th>' + (prof ? '<th>' + L('الربح', 'Profit') + '</th>' : '') + '</tr>' + prods.slice(0, 200).map(function (p) { return '<tr><td>' + U.esc(p.n) + '</td><td class="num">' + p.q + '</td><td class="num">' + U.money(p.v) + '</td><td class="num">' + (p.d > 0.004 ? '<b style="color:var(--bad)">−' + U.money(p.d) + '</b>' : '<span class="muted">—</span>') + '</td>' + (prof ? '<td class="num" style="color:var(--ok)">' + U.money(p.pr) + '</td>' : '') + '</tr>'; }).join('') + '</table></div></div>';
    bindRange('rr', st, function () { V.render(el); });
    drawBars($('#rch'), dk.map(function (d) { return d.slice(8) + '/' + d.slice(5, 7); }), dk.map(function (d) { return days[d] || 0; }));
    if ($('#rx')) $('#rx').onclick = function () { var rows = [[L('الصنف', 'Product'), L('الكمية', 'Qty'), L('المبيعات', 'Sales')].concat(prof ? [L('الربح', 'Profit')] : [])]; prods.forEach(function (p) { rows.push([p.n, p.q, U.r2(p.v)].concat(prof ? [U.r2(p.pr)] : [])); }); saveBlob(XL.writeXlsx(rows, 'Report', lang() !== 'en'), 'report_' + st.from + '_' + st.to + '.xlsx'); };
    $('#rpr').onclick = function () { Printer.print('<h2>' + U.esc(shopName()) + ' — ' + L('تقرير المبيعات', 'Sales report') + '</h2><p>' + st.from + ' → ' + st.to + '</p><p>' + L('صافي المبيعات: ', 'Net sales: ') + U.money(sum.total) + (prof ? ' — ' + L('الربح: ', 'Profit: ') + U.money(sum.profit) : '') + '</p><table border="1" cellpadding="5" style="border-collapse:collapse;width:100%">' + prods.map(function (p) { return '<tr><td>' + U.esc(p.n) + '</td><td>' + p.q + '</td><td>' + U.money(p.v) + '</td></tr>'; }).join('') + '</table>', { css: '@page{size:A4;margin:12mm}body{font-family:Tahoma,Arial}', silent: false, dir: lang() === 'en' ? 'ltr' : 'rtl' }); };
  }
};

