    $('#nps', m).onclick = function () { var a = $('#np', m).value; if (a.length < 4) return toast(L('4 أحرف على الأقل', 'At least 4 characters'), 'bad'); if (a !== $('#np2', m).value) return toast(L('غير متطابقة', 'Does not match'), 'bad'); Sec.hash(a).then(function (h) { u.salt = h.salt; u.hash = h.hash; u.mustChange = false; Store.log('user.password', u.username); Store.save(); Modal.close(m); toast(L('تم التغيير', 'Changed'), 'ok'); }); };
