/* ---------- close hook: save + backup when the program closes ---------- */
if (IS_ELECTRON) {
  window.addEventListener('beforeunload', function () { try { Store.saveNow(); } catch (e) { } }); // backup is done by Closing.run before the window is allowed to close
} else if (IS_NW) {
  try {
    nw.Window.get().on('close', function () {
      var w = this; try { Store.saveNow(); if (Store.db && S().backup.onClose) Backup.run('close'); } catch (e) { }
      w.close(true);
    });
  } catch (e) { }
}
